        result = apis.venmo.remind_payment_request(
            access_token=token,
            payment_request_id=req['payment_request_id']
        )
        reminders_sent += 1
        print(f"Reminder sent to {req['receiver']['name']} for ${req['amount']}")
    except Exception as e:
        print(f"Failed to send reminder to {req['receiver']['name']}: {e}")

print(f"\nTotal reminders sent: {reminders_sent}")

# Get library albums
all_album_songs = set()
page_index = 0
while True:
    response = apis.spotify.get_my_library_albums(access_token=token, page_index=page_index)
    if not response['albums']:
        break
    for album in response['albums']:
        # Get songs from each album
        songs_response = apis.spotify.get_album_songs(access_token=token, album_id=album['id'], page_index=0)
        if 'songs' in songs_response:
            for song in songs_response['songs']:
                all_album_songs.add(song['id'])
    page_index += 1

print(f"Total album songs: {len(all_album_songs)}")

