# Now filter for transactions sent by Jose in May 2023
token = '<REDACTED:6ba06ef8>'

# Get all sent transactions again and filter for May 2023
sent_transactions_may = []

for page in range(1, 10):
    transactions = apis.venmo.show_transactions(access_token=token, page_index=page)
    if not transactions:
        break

    for trans in transactions:
        if trans['sender']['email'] == 'joseharr@gmail.com':
            # Check if created in May 2023
            if trans['created_at'].startswith('2023-05'):
                sent_transactions_may.append(trans)

print(f"Transactions sent by Jose in May 2023: {len(sent_transactions_may)}")
for trans in sent_transactions_may:
    print(f"  - {trans['description']}: {trans['like_count']} likes (created: {trans['created_at']})")

# Calculate total likes
total_likes = sum(trans['like_count'] for trans in sent_transactions_may)
print(f"\nTotal likes on transactions sent by Jose in May 2023: {total_likes}")

