# First, let's see the full result to understand the structure better
print(f"Total transactions in result: {len(result)}")

# Check all transactions and their dates
all_dates = {}
for tx in result:
    date = tx['created_at'][:7]  # Get YYYY-MM
    if date not in all_dates:
        all_dates[date] = 0
    all_dates[date] += 1

print("\nTransactions by month:")
for month in sorted(all_dates.keys()):
    print(f"  {month}: {all_dates[month]} transactions")

all_playlist_songs = []
page_index = 0
while True:
    playlists_response = apis.spotify.get_playlists(access_token=token, page_index=page_index)
    if not playlists_response['playlists']:
        break
    for playlist in playlists_response['playlists']:
        if 'songs' in playlist:
            all_playlist_songs.extend(playlist['songs'])
    page_index += 1

print(f"Total songs from playlists: {len(all_playlist_songs)}")
if all_playlist_songs:
    print("Sample playlist song:")
    print(all_playlist_songs[0])

# Collect all songs from songs, albums, and playlists
rb_songs = []

# From songs library
for song in all_songs:
    if 'genre' in song and 'r&b' in song['genre'].lower():
        rb_songs.append({
            'title': song.get('title'),
            'play_count': song.get('play_count', 0)
        })

# From albums
albums = albums_response.get('albums', [])
for album in albums:
    for song in album.get('songs', []):
        if 'genre' in song and 'r&b' in song['genre'].lower():
            rb_songs.append({
                'title': song.get('title'),
                'play_count': song.get('play_count', 0)
            })

# From playlists
playlists = playlists_response.get('playlists', [])
for playlist in playlists:
    for song in playlist.get('songs', []):
        if 'genre' in song and 'r&b' in song['genre'].lower():
            rb_songs.append({
                'title': song.get('title'),
                'play_count': song.get('play_count', 0)
            })

# Sort by play count and get top 4
rb_songs_sorted = sorted(rb_songs, key=lambda x: x['play_count'], reverse=True)
top_4 = rb_songs_sorted[:4]

print("Top 4 R&B songs:")
for song in top_4:
    print(f"{song['title']}: {song['play_count']} plays")

# Create comma-separated list
top_4_titles = [song['title'] for song in top_4]
result = ', '.join(top_4_titles)
print(f"\nResult: {result}")

